mapper.select:
SELECT v.id AS venueId, v.venue_name AS venueName, COUNT(b.id) AS totalBookings, SUM(CASE WHEN b.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedBookings, COALESCE(SUM(b.duration_hours), 0) AS totalHours, COALESCE(SUM(b.fee_amount), 0) AS totalRevenue FROM venue v LEFT JOIN booking b ON v.id = b.venue_id
AND b.booking_date >= #{startDate}
AND b.booking_date <= #{endDate}
AND v.id = #{venueId}
GROUP BY v.id, v.venue_name ORDER BY totalBookings DESC

SELECT a.id AS activityId, a.title AS activityTitle, COUNT(r.id) AS totalRegistrations, SUM(CASE WHEN r.audit_status = 'APPROVED' THEN 1 ELSE 0 END) AS approvedCount FROM activity a LEFT JOIN activity_registration r ON a.id = r.activity_id
AND r.created_at >= #{startDate}
AND r.created_at <= #{endDate}
AND a.category_id = #{categoryId}
GROUP BY a.id, a.title ORDER BY totalRegistrations DESC
